function IH46ThemeButtons({site,copy}){return <div className="template-switch" role="group" aria-label={copy.theme}><button type="button" aria-pressed={site.template==="classic"} onClick={()=>site.setTemplate("classic")}><i className="swatch mono"/>{copy.mono}</button><button type="button" aria-pressed={site.template!=="classic"} onClick={()=>site.setTemplate("current")}><i className="swatch"/>{copy.turquoise}</button></div>;}
