function IH46Page({session,loading,categoryGroups=[],overlay}){
 const homeRootRef=useRef(null),canvasRef=useRef(null),headerRef=useRef(null),headerSlotRef=useRef(null),mobileMenuButtonRef=useRef(null);
 const [mobileMenuOpen,setMobileMenuOpen]=useState(false);
 const site=useSitePreferences(),english=site.language==="en",mono=site.template==="classic",dark=site.theme==="dark",copy=IH46_COPY[english?"en":"pl"];
 const palette=IDEA_HIRE_VISUAL_SYSTEM[mono?(dark?"monoDark":"mono"):(dark?"turquoiseDark":"turquoise")];
 useIdeaHireScrollHeader(headerRef,headerSlotRef,true);

  const [hasNotifications, setHasNotifications] = useState(false);
  const [recentJobs, setRecentJobs] = useState(fallbackJobs);
  const [activeJobIndex, setActiveJobIndex] = useState(0);
  const navigate = useNavigate();

  useEffect(() => {
    let mounted = true;

    checkNotifications(session);

    function handleNotificationsRead(
      event
    ) {
      if (
        !event?.detail?.userId ||
        event.detail.userId ===
          session?.user?.id
      ) {
        setHasNotifications(false);
      }
    }

    function handleStorage(event) {
      if (
        event.key ===
        `ideahire_read_notifications_${session?.user?.id}`
      ) {
        checkNotifications(session);
      }
    }

    window.addEventListener(
      "ideahire:notifications-read",
      handleNotificationsRead
    );

    window.addEventListener(
      "storage",
      handleStorage
    );

    const interval = setInterval(() => {
      if (mounted) {
        checkNotifications(session);
      }
    }, 10000);

    return () => {
      mounted = false;
      clearInterval(interval);

      window.removeEventListener(
        "ideahire:notifications-read",
        handleNotificationsRead
      );

      window.removeEventListener(
        "storage",
        handleStorage
      );
    };
  }, [session?.user?.id]);

  useEffect(() => {
    let mounted = true;

    async function loadRecentJobs() {
      try {
        const { data, error } =
          await supabase
            .from("jobs")
            .select(
              "id, title, description, category, budget, created_at"
            )
            .order("created_at", {
              ascending: false,
            })
            .limit(8);

        if (error) {
          console.error(
            "HOME RECENT JOBS ERROR:",
            error
          );
          return;
        }

        if (
          mounted &&
          Array.isArray(data) &&
          data.length > 0
        ) {
          setRecentJobs(data);
          setActiveJobIndex(0);
        }
      } catch (error) {
        console.error(
          "HOME RECENT JOBS ERROR:",
          error
        );
      }
    }

    loadRecentJobs();

    const channel = supabase
      .channel("home-recent-jobs")
      .on(
        "postgres_changes",
        {
          event: "INSERT",
          schema: "public",
          table: "jobs",
        },
        () => {
          loadRecentJobs();
        }
      )
      .subscribe();

    return () => {
      mounted = false;
      supabase.removeChannel(channel);
    };
  }, []);

  useEffect(() => {
    if (recentJobs.length <= 1) return undefined;

    const interval = window.setInterval(
      () => {
        setActiveJobIndex(
          (current) =>
            (current + 1) % recentJobs.length
        );
      },
      4500
    );

    return () => {
      window.clearInterval(interval);
    };
  }, [recentJobs.length]);

  async function checkNotifications(currentSession) {
    const userId = currentSession?.user?.id;

    if (!userId) {
      setHasNotifications(false);
      return;
    }

    try {
      const { data: myJobs, error: jobsError } = await supabase
        .from("jobs")
        .select("id")
        .eq("user_id", userId);

      if (jobsError) {
        console.error("HOME NOTIFICATION JOBS ERROR:", jobsError);
        return;
      }

      const jobIds = (myJobs || []).map((job) => job.id);

      let applications = [];

      if (jobIds.length > 0) {
        const {
          data,
          error: applicationsError,
        } = await supabase
          .from("job_applications")
          .select("id, job_id, applicant_id, created_at")
          .in("job_id", jobIds)
          .eq("status", "pending")
          .order("created_at", { ascending: false });

        if (applicationsError) {
          console.error(
            "HOME NOTIFICATION APPLICATIONS ERROR:",
            applicationsError
          );
          return;
        }

        applications = data || [];
      }

      const readKey = `ideahire_read_notifications_${userId}`;

      let readIds = [];

      try {
        const storedReadIds = JSON.parse(
          localStorage.getItem(readKey) || "[]"
        );

        readIds = Array.isArray(storedReadIds)
          ? storedReadIds
          : [];
      } catch {
        readIds = [];
      }

      const [
        rejectedResult,
        acceptedResult,
        blockedResult,
      ] = await Promise.all([
        supabase
          .from("job_applications")
          .select("id")
          .eq("applicant_id", userId)
          .eq("status", "rejected"),

        supabase
          .from("job_applications")
          .select("id")
          .eq("applicant_id", userId)
          .eq("status", "accepted"),

        supabase
          .from("user_blocks")
          .select("id")
          .eq("blocked_id", userId),
      ]);

      if (rejectedResult.error) {
        console.error(
          "HOME REJECTED NOTIFICATIONS ERROR:",
          rejectedResult.error
        );
      }

      if (acceptedResult.error) {
        console.error(
          "HOME ACCEPTED NOTIFICATIONS ERROR:",
          acceptedResult.error
        );
      }

      if (blockedResult.error) {
        console.error(
          "HOME BLOCK NOTIFICATIONS ERROR:",
          blockedResult.error
        );
      }

      const hasUnreadIncoming =
        (applications || []).some(
          (application) =>
            !readIds.includes(
              `incoming:${application.id}`
            )
        );

      const hasUnreadRejected =
        (rejectedResult.data || []).some(
          (application) =>
            !readIds.includes(
              `rejected:${application.id}`
            )
        );

      const hasUnreadAccepted =
        (acceptedResult.data || []).some(
          (application) =>
            !readIds.includes(
              `accepted:${application.id}`
            )
        );

      const hasUnreadBlock =
        (blockedResult.data || []).some(
          (block) =>
            !readIds.includes(
              `blocked:${block.id}`
            )
        );

      setHasNotifications(
        hasUnreadIncoming ||
          hasUnreadRejected ||
          hasUnreadAccepted ||
          hasUnreadBlock
      );
    } catch (error) {
      console.error("HOME NOTIFICATION CHECK ERROR:", error);
    }
  }

  async function handleLogout() {
    const { error } = await supabase.auth.signOut();

    if (error) {
      alert(`Nie udało się wylogować: ${error.message}`);
      return;
    }

    navigate("/");
  }

  const userName =
    session?.user?.user_metadata?.name ||
    session?.user?.email?.split("@")[0] ||
    "Użytkownik";

  const avatarUrl =
    session?.user?.user_metadata
      ?.avatar_url || "";

  const userInitial = userName
    .charAt(0)
    .toUpperCase();

  const activeJob =
    recentJobs[
      activeJobIndex % recentJobs.length
    ] || fallbackJobs[0];

  const nextJob =
    recentJobs[
      (activeJobIndex + 1) %
        recentJobs.length
    ] || fallbackJobs[1];

  const followingJob =
    recentJobs[
      (activeJobIndex + 2) %
        recentJobs.length
    ] || fallbackJobs[2];

  function formatBudget(value) {
    return `${Number(
      value || 0
    ).toLocaleString("pl-PL")} zł`;
  }


 const stage=useIH46Film(homeRootRef,canvasRef,palette,mono,dark,english,recentJobs,mobileMenuOpen);
 useIH46Reveal(homeRootRef,stage.reduced);
 function anchor(hash){const id=hash.slice(1),element=homeRootRef.current?.querySelector('[id="'+id.replace(/[^a-z0-9_-]/gi,"")+'"]');element?.scrollIntoView({behavior:stage.reduced?"instant":"smooth",block:"start"});if(id==="ih46-content")element?.focus({preventScroll:true});}
 function linkClick(e){const a=e.target.closest?.('a[href^="#"]');if(a){e.preventDefault();anchor(a.getAttribute("href"));}}
 useEffect(()=>{if(window.location.hash){const frame=requestAnimationFrame(()=>anchor(window.location.hash));return()=>cancelAnimationFrame(frame);}},[]);
 return <><div ref={homeRootRef} className="site" data-paused={stage.paused||stage.reduced} data-reduced={stage.reduced} data-no-translate="true" onClick={linkClick}>
  <div className="fallback-world" aria-hidden="true"><span>IDEA<br/>HIRE</span></div><canvas ref={canvasRef} className="world" aria-hidden="true"/>
  <div className="view"><a className="skip" href="#ih46-content">{english?"Skip to content":"Przejdź do treści"}</a>
  <div ref={headerSlotRef} className="header-slot"><header ref={headerRef} className="masthead"><IH46FeeStrip english={english}/><div className="navigation"><IH46Brand/><nav className="quick-nav" aria-label={copy.menu}><a href="#how-it-works">{copy.how}</a><a href="#categories">{copy.categories}</a><a href="#commission">{copy.fee}</a></nav><div className="header-tools"><button type="button" className="palette-now" onClick={()=>setMobileMenuOpen(true)} aria-label={copy.theme}><i className={"swatch"+(mono?" mono":"")}/><span>{mono?copy.mono:copy.turquoise}</span></button>{session?<Link className="avatar" to="/account" aria-label={copy.account}>{avatarUrl?<img src={avatarUrl} alt=""/>:<span>{userInitial}</span>}{hasNotifications&&<i/>}</Link>:<Link className="login-link" to="/login">{copy.login}</Link>}<button ref={mobileMenuButtonRef} className="menu-trigger" type="button" onClick={()=>setMobileMenuOpen(true)} aria-expanded={mobileMenuOpen} aria-controls="ih46-menu" aria-label={copy.menu}><span>{copy.menu}</span><IH46Burger/></button></div></div></header></div>
  <main id="ih46-content" tabIndex={-1}><IH46Hero stage={stage} english={english} copy={copy}/><section className="paths" aria-label={english?"Choose your next step":"Wybierz swój następny krok"}><Link to="/find-talent"><IH46Mark/><span><small>{english?"I have a project":"Mam projekt"}</small><strong>{english?"I need a professional.":"Szukam wykonawcy."}</strong></span><IH46Arrow/></Link><Link to="/jobs"><IH46Mark/><span><small>{english?"I have the skills":"Mam umiejętności"}</small><strong>{english?"I need a project.":"Szukam zlecenia."}</strong></span><IH46Arrow/></Link></section>
   <IH46Jobs jobs={recentJobs} english={english} copy={copy} onHighlight={stage.highlight}/><IH46Categories groups={categoryGroups.length?categoryGroups:categories} english={english} copy={copy}/><IH46How english={english} copy={copy}/><IH46Commission english={english} copy={copy}/>
   <section className="section closing" data-reveal><IH46Mark/><h2>{copy.closing.map(line=><span key={line}>{line}</span>)}</h2><Link className="button primary" to={session?"/account":"/register"}>{session?copy.account:copy.register}<IH46Arrow/></Link></section>
  </main><footer className="footer"><div><IH46Brand/><p>{copy.summary}</p></div><nav aria-label={copy.legal}><a href={helpCenterHref()} onClick={e=>{e.currentTarget.href=helpCenterHref();}} referrerPolicy="no-referrer">{copy.help}</a><Link to="/regulamin">{copy.terms}</Link><Link to="/polityka-prywatnosci">{copy.privacy}</Link><Link to="/polityka-cookies">Cookies</Link><a href="mailto:ideahireprywatnosc@gmail.com?subject=Zg%C5%82oszenie%20nielegalnej%20tre%C5%9Bci%20w%20IdeaHire">{copy.illegal}</a></nav><span>© {new Date().getFullYear()} IdeaHire</span></footer></div>
 </div><IH46Menu open={mobileMenuOpen} onClose={()=>setMobileMenuOpen(false)} rootRef={homeRootRef} triggerRef={mobileMenuButtonRef} site={site} copy={copy} session={session} hasNotifications={hasNotifications} logout={handleLogout} overlay={overlay} onAnchor={anchor}/></>;
}

/* Shadow DOM odcina historyczne reguły globalne; kontekst React i routing pozostają wspólne. */
function App(props){
 const host=useRef(null),[mount,setMount]=useState(null),site=useSitePreferences();
 const mono=site.template==="classic",dark=site.theme==="dark",palette=IDEA_HIRE_VISUAL_SYSTEM[mono?(dark?"monoDark":"mono"):(dark?"turquoiseDark":"turquoise")];
 useLayoutEffect(()=>{const element=host.current,shadow=element.shadowRoot||element.attachShadow({mode:"open"});let view=shadow.querySelector('[data-view-mount]'),overlay=shadow.querySelector('[data-overlay-mount]');if(!view){const style=document.createElement("style");style.textContent=IH46_STYLES;view=document.createElement("div");overlay=document.createElement("div");view.dataset.viewMount="";overlay.dataset.overlayMount="";shadow.append(style,view,overlay);}setMount({view,overlay});
  const guard=document.createElement("style");guard.textContent='body.ih46-page{margin:0!important;background:var(--v-bg)!important;color:var(--v-ink)!important}body.ih46-page #root{width:100%!important;max-width:none!important;margin:0!important;padding:0!important;text-align:left!important;overflow:visible!important}body.ih46-page [data-ideahire-stage-host]{display:block!important;width:100%!important;min-height:100svh!important;margin:0!important;padding:0!important;transform:none!important;filter:none!important;contain:none!important}body.ih46-page .site-preferences{display:none!important}';document.head.appendChild(guard);document.body.classList.add("ih46-page");return()=>{guard.remove();document.body.classList.remove("ih46-page");};
 },[]);
 useLayoutEffect(()=>{const element=host.current;Object.entries(palette).forEach(([key,value])=>element.style.setProperty("--"+key,value));},[palette]);
 return <div ref={host} data-ideahire-stage-host="p46" data-no-translate="true">{mount&&createPortal(<IH46Page {...props} overlay={mount.overlay}/>,mount.view)}</div>;
}

export default App;
